import{_ as e,c as i,o,ae as n}from"./chunks/framework.BQlYxExx.js";const r="/images/preferencje.png",t="/images/podglad_zwierzaka.png",y=JSON.parse('{"title":"Dokumentacja Użytkownika","description":"","frontmatter":{},"headers":[],"relativePath":"dokumentacja-uzytkownika.md","filePath":"dokumentacja-uzytkownika.md"}'),s={name:"dokumentacja-uzytkownika.md"};function k(z,a,c,d,p,l){return o(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="dokumentacja-uzytkownika" tabindex="-1">Dokumentacja Użytkownika <a class="header-anchor" href="#dokumentacja-uzytkownika" aria-label="Permalink to &quot;Dokumentacja Użytkownika&quot;">​</a></h1><p>Dokumentacja użytkownika wyjaśnia, jak korzystać z aplikacji ŁapGo, od pierwszego zalogowania po nawiązanie kontaktu ze schroniskiem.</p><h2 id="_8-1-przewodnik-uzytkownika-user-guide" tabindex="-1">8.1. Przewodnik Użytkownika (User Guide) <a class="header-anchor" href="#_8-1-przewodnik-uzytkownika-user-guide" aria-label="Permalink to &quot;8.1. Przewodnik Użytkownika (User Guide)&quot;">​</a></h2><h3 id="_1-ustawianie-preferencji-i-dopasowanie" tabindex="-1">1. Ustawianie preferencji i Dopasowanie <a class="header-anchor" href="#_1-ustawianie-preferencji-i-dopasowanie" aria-label="Permalink to &quot;1. Ustawianie preferencji i Dopasowanie&quot;">​</a></h3><p>Aplikacja ŁapGo działa najlepiej, gdy poznasz swoje potrzeby. Po rejestracji i zalogowaniu zostaniesz poprowadzony do strony ustawiania preferencji:</p><ol><li>Na ekranie Preferencji (dostępnym przez ikonę profilu lub menu nawigacyjne) wybierz interesujący Cię gatunek (pies, kot, inne).</li><li>Precyzyjnie określ kryteria, takie jak Wiek, Wielkość (małe, średnie, duże) oraz Lokalizacja (wprowadź miasto, a system zaproponuje zwierzęta w określonym promieniu).</li><li>Po zapisaniu preferencji, Dashboard automatycznie wyświetli zwierzęta, które w największym stopniu spełniają Twoje kryteria.</li></ol><p><img src="'+r+'" alt="Podgląd widoku preferencji"><em>Rysunek 7: Podgląd widoku preferencji</em></p><h3 id="_2-wyszukiwanie-i-filtrowanie" tabindex="-1">2. Wyszukiwanie i Filtrowanie <a class="header-anchor" href="#_2-wyszukiwanie-i-filtrowanie" aria-label="Permalink to &quot;2. Wyszukiwanie i Filtrowanie&quot;">​</a></h3><p>Jeśli chcesz przeglądać zwierzęta poza ustawionymi preferencjami:</p><ol><li>Przejdź do zakładki Zwierzęta</li><li>Użyj zaawansowanych filtrów bocznych, aby zawęzić wyniki po dodatkowych kryteriach, takich jak Cechy (Tagi, np. &quot;przyjazny&quot;, &quot;aktywny&quot;).</li><li>Wyniki możesz sortować według Daty Dodania lub Odległości od Twojej lokalizacji.</li></ol><h3 id="_3-proces-adopcji-i-kontakt-ze-schroniskiem" tabindex="-1">3. Proces Adopcji i Kontakt ze Schroniskiem <a class="header-anchor" href="#_3-proces-adopcji-i-kontakt-ze-schroniskiem" aria-label="Permalink to &quot;3. Proces Adopcji i Kontakt ze Schroniskiem&quot;">​</a></h3><ol><li>Kliknij na wybrane zwierzę, aby zobaczyć jego Szczegóły (zdjęcia, opis, historia).</li><li>W sekcji szczegółów znajdziesz bezpośrednie dane kontaktowe do schroniska (telefon, e-mail) oraz link do ich strony.</li><li>Aplikacja ŁapGo nie jest stroną adopcyjną. Pełni rolę pośrednika. Cały proces adopcyjny (rozmowy, wizyty przedadopcyjne) prowadzony jest bezpośrednio ze Schroniskiem.</li></ol><p><img src="'+t+'" alt="Podgląd widoku zwierzaka"><em>Rysunek 8: Podgląd widoku zwierzaka</em></p><h2 id="_8-2-faq-najczesciej-zadawane-pytania" tabindex="-1">8.2. FAQ (Najczęściej Zadawane Pytania) <a class="header-anchor" href="#_8-2-faq-najczesciej-zadawane-pytania" aria-label="Permalink to &quot;8.2. FAQ (Najczęściej Zadawane Pytania)&quot;">​</a></h2><ul><li><p><strong>Czy ŁapGo prowadzi proces adopcyjny?</strong> Nie. Jesteśmy tylko agregatorem ogłoszeń. Cały proces adopcyjny jest prowadzony przez schronisko, w którym przebywa zwierzę.</p></li><li><p><strong>Jak często aktualizują się ogłoszenia?</strong> Agregacja danych odbywa się automatycznie co 24 godziny. Najważniejsze dane są weryfikowane przez AI (Gemini API) i potwierdzane przez administratorów.</p></li><li><p><strong>Co mam zrobić, jeśli ogłoszenie jest nieaktualne?</strong> Prosimy o kontakt ze schroniskiem lub zgłoszenie błędu za pośrednictwem formularza na stronie.</p></li></ul>',15)])])}const u=e(s,[["render",k]]);export{y as __pageData,u as default};
